-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): fiscal capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- INTERMEDIATE
--   Fields read with the switch on: psc_total_tax_musd.
--   The Designer printed no total tax per regime.
--   APPENDED: Read the figures in the Fiscal Regime Designer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping. Its Summary tab then
--   shows the total tax for each regime.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/fiscal.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- fiscal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'fiscal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 fiscal refused: fiscal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '5be2b3a132aec8daf747058cda0298e3' and fields = '[{"key": "psc_y1_cost_recovered_musd", "tol": 0.001, "unit": "million USD", "label": "Cost recovered in year 1", "expected": 70.19798552}, {"key": "psc_y3_unrecovered_pool_musd", "tol": 0.001, "unit": "million USD", "label": "Unrecovered cost pool out of year 3", "expected": 190.0287098892603}, {"key": "psc_y5_r_factor", "tol": 0.000001, "unit": "ratio", "label": "R factor in year 5", "expected": 1.1122624290891505}, {"key": "psc_y8_royalty_musd", "tol": 0.0003, "unit": "million USD", "label": "Royalty in year 8", "expected": 5.961300665865362}, {"key": "psc_total_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Total tax over the life", "expected": 62.454042497773344}, {"key": "psc_npv_musd", "tol": 0.05, "unit": "million USD", "label": "NPV at the project rate", "expected": -19.724017651298347}]'::jsonb then 'old'
              when md5(prompt) = '4def1722f9f77be0263f7c101e5384c4' and fields = '[{"key": "psc_y1_cost_recovered_musd", "tol": 0.001, "unit": "million USD", "label": "Cost recovered in year 1", "expected": 70.19798552}, {"key": "psc_y3_unrecovered_pool_musd", "tol": 0.001, "unit": "million USD", "label": "Unrecovered cost pool out of year 3", "expected": 190.0287098892603}, {"key": "psc_y5_r_factor", "tol": 0.000001, "unit": "ratio", "label": "R factor in year 5", "expected": 1.1122624290891505}, {"key": "psc_y8_royalty_musd", "tol": 0.0003, "unit": "million USD", "label": "Royalty in year 8", "expected": 5.961300665865362}, {"key": "psc_total_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Total tax over the life", "expected": 62.454042497773344}, {"key": "psc_npv_musd", "tol": 0.05, "unit": "million USD", "label": "NPV at the project rate", "expected": -19.724017651298347}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'fiscal' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w3 fiscal refused: fiscal/intermediate matches neither its post-W1 form (prompt md5 5be2b3a132aec8daf747058cda0298e3) nor its W3 form (prompt md5 4def1722f9f77be0263f7c101e5384c4), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 fiscal: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 fiscal refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for the SAME URUAN project as the Associate capstone (identical production, deck, costs and discount rate), now under a production sharing contract. The regime: royalty sliding on the oil price, 6 percent from a threshold of 0 USD/bbl and 9.5 percent from a threshold of 60 USD/bbl; cost recovery limit 65 percent; profit split tiered on the R factor, 65 percent to the contractor from R 1.0, 45 percent from R 1.4 and 32 percent from R 1.65; corporate income tax 32 percent, no resource rent tax and no minimum tax. Report: (1) the COST RECOVERED in year 1, in millions of USD; (2) the UNRECOVERED COST POOL carried out of year 3, in millions of USD; (3) the R FACTOR in year 5, as a ratio; (4) the ROYALTY in year 8, in millions of USD; (5) the TOTAL tax over the life, in millions of USD; and (6) the NPV at the project''s own discount rate, in millions of USD. Traps. The recoverable pool is the balance brought forward PLUS this year''s capex PLUS this year''s opex, and the allowance is the limit as a percent of revenue AFTER royalty, not of gross revenue. The royalty rate is read from the applied oil price for the year, and the deck steps at year 8, so field 4 is the FIRST year on the far side of that step: a reader who puts the step a year later reads year 8 at the old price and at the lower tier, and is wrong twice over. The R factor is cumulative revenue over cumulative cost, a ratio of CUMULATIVES including the current year, and it is computed before the split is chosen; a reader who takes the year''s own revenue over the year''s own cost gets a different number in every year. The tax base is the contractor''s PROFIT SHARE alone: cost is compensated through cost recovery and is not deducted again here. The R factor crosses all three tranches on this field and then FALLS BACK through the top one in the final year, stepping the contractor''s split back UP, so a reader who assumes the split ratchets once given up is wrong in year 25 and therefore wrong on fields 5 and 6. Discounting is YEAR END, so year 1 is already discounted once, and the NPV may be negative. Read the figures in the Fiscal Regime Designer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping. Its Summary tab then shows the total tax for each regime.'
     where app_slug = 'fiscal' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 fiscal refused: fiscal/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4def1722f9f77be0263f7c101e5384c4' and fields = '[{"key": "psc_y1_cost_recovered_musd", "tol": 0.001, "unit": "million USD", "label": "Cost recovered in year 1", "expected": 70.19798552}, {"key": "psc_y3_unrecovered_pool_musd", "tol": 0.001, "unit": "million USD", "label": "Unrecovered cost pool out of year 3", "expected": 190.0287098892603}, {"key": "psc_y5_r_factor", "tol": 0.000001, "unit": "ratio", "label": "R factor in year 5", "expected": 1.1122624290891505}, {"key": "psc_y8_royalty_musd", "tol": 0.0003, "unit": "million USD", "label": "Royalty in year 8", "expected": 5.961300665865362}, {"key": "psc_total_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Total tax over the life", "expected": 62.454042497773344}, {"key": "psc_npv_musd", "tol": 0.05, "unit": "million USD", "label": "NPV at the project rate", "expected": -19.724017651298347}]'::jsonb) from public.academy_capstones where app_slug = 'fiscal' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 fiscal refused: fiscal/intermediate does not read back as its W3 form';
  end if;

  raise notice 'w3 fiscal: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
